import pandas as pd


def daily_active_users(events: pd.DataFrame) -> pd.DataFrame:
    columns = ["date", "dau", "dau_7d_avg"]
    if events.empty:
        return pd.DataFrame(columns=columns)
    days = pd.to_datetime(events["ts"], utc=True).dt.normalize()
    dau = events.groupby(days)["user_id"].nunique()
    full_range = pd.date_range(dau.index.min(), dau.index.max(), freq="D")
    dau = dau.reindex(full_range, fill_value=0).astype(int)
    return pd.DataFrame({
        "date": [d.date() for d in dau.index],
        "dau": dau.to_numpy(),
        "dau_7d_avg": dau.rolling(7, min_periods=1).mean().round(2).to_numpy(),
    })
